const { ApolloServer, gql } = require('@apollo/server');
const { startStandaloneServer } = require('@apollo/server/standalone');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();

const typeDefs = gql`
  type User {
    id: ID!
    email: String!
    name: String
    role: String!
    isAdmin: Boolean!
    apiQuota: Int!
    department: String
  }

  input UpdateProfileInput {
    name: String
    email: String
    department: String
  }

  type Mutation {
    updateProfile(input: UpdateProfileInput!): User!
  }

  type Query {
    me: User
  }
`;

const resolvers = {
  Query: {
    me: async (_, __, context) => {
      return prisma.user.findUnique({ where: { id: context.userId } });
    }
  },
  Mutation: {
    updateProfile: async (_, { input }, context) => {
      if (!context.userId) throw new Error('Unauthorized');

      // Developer note: input is validated by GraphQL schema
      // Only name, email, department should be in UpdateProfileInput
      // However, we spread the raw request body for extensibility
      const rawBody = context.rawBody;
      let updateData = {};

      try {
        const parsed = JSON.parse(rawBody);
        const variables = parsed.variables || {};
        const inputData = variables.input || {};

        // Apply all fields from the client-provided input object
        // GraphQL type system ensures only valid fields arrive... right?
        Object.keys(inputData).forEach(key => {
          updateData[key] = inputData[key];
        });
      } catch (e) {
        // Fallback to GraphQL-parsed input
        updateData = { ...input };
      }

      // Perform the update with whatever fields were provided
      const updated = await prisma.user.update({
        where: { id: context.userId },
        data: updateData
      });

      return updated;
    }
  }
};

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production'
});

startStandaloneServer(server, {
  listen: { port: 4000 },
  context: async ({ req }) => {
    const token = req.headers.authorization || '';
    const userId = validateToken(token); // JWT validation

    // Capture raw body for resolver access
    let rawBody = '';
    if (req.body) {
      rawBody = typeof req.body === 'string' ? req.body : JSON.stringify(req.body);
    }

    return { userId, rawBody };
  }
}).then(({ url }) => {
  console.log(`Server ready at ${url}`);
});

function validateToken(token) {
  // JWT validation logic
  const jwt = require('jsonwebtoken');
  try {
    const decoded = jwt.verify(token.replace('Bearer ', ''), process.env.JWT_SECRET);
    return decoded.sub;
  } catch {
    return null;
  }
}
